// src/utils/resposta.js
function sucesso(res, dados, status = 200) {
    return res.status(status).json({ sucesso: true, dados });
}

function erro(res, mensagem, status = 400) {
    return res.status(status).json({ sucesso: false, mensagem });
}

module.exports = { sucesso, erro };

// livroController.js
const { sucesso } = require("../utils/resposta");

async function listar(req, res, next) {
    try {
        const livros = await livroService.listarLivros();
        sucesso(res, livros);
    } catch (erro) {
        next(erro);
    }
}

// src/middlewares/errorHandler.js
function errorHandler(err, req, res, next) {
    console.error(err);
    res.status(err.status || 500).json({
        sucesso: false,
        mensagem: err.message || "Erro interno do servidor."
    });
}

// src/config/logger.js
const winston = require("winston");

const logger = winston.createLogger({
    level: "info",
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: "logs/erros.log", level: "error" })
    ]
});

module.exports = logger;

const logger = require("../config/logger");

function errorHandler(err, req, res, next) {
    const status = err.status || 500;
    logger.error(err.message, { rota: req.originalUrl, metodo: req.method });

    // erro inesperado (500): o detalhe fica so no log
    const mensagem = status === 500 ? "Erro interno do servidor." : err.message;
    res.status(status).json({ sucesso: false, mensagem });
}

// src/app.js -- monta o app, sem ligar o servidor
require("dotenv").config();

const express = require("express");
const livroRoutes = require("./routes/livroRoutes");
const errorHandler = require("./middlewares/errorHandler");

const app = express();
app.use(express.json());
app.use("/livros", livroRoutes);
// ... as demais rotas
app.use(errorHandler);

module.exports = app;

// server.js -- so liga o servidor
const app = require("./src/app");

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
    console.log(`Servidor executando na porta ${PORT}`);
});

// tests/livros.test.js
const request = require("supertest");
const app = require("../src/app");

describe("GET /livros", () => {
    it("deve retornar status 200 e uma lista de livros", async () => {
        const resposta = await request(app).get("/livros");

        expect(resposta.status).toBe(200);
        expect(Array.isArray(resposta.body.dados)).toBe(true);
    });
});

"scripts": {
    "test": "jest"
}

